/* Real YMFM proof: frontend transitions do not stop/restart Theme0; native
 * Options toggles still play/stop it. All campaign audio remains original. */
#define main prior_full_frontend_load_test
#include "test_em_web_frontend_load.c"
#undef main
static unsigned theme_play,theme_stop,driver_reset,pitch_updates;static uint8_t last_pitch[24];static uint64_t pitch_frame;
static void music_step(void){em_web_campaign.frontend_hold=1;unsigned sp=em_cpu.a[7]&65535;if(sp<=65528){if(em_cpu.pc==0x1664&&dune_long(&em_cpu,sp+4)==0)++theme_play;if(em_cpu.pc==0x167a&&dune_long(&em_cpu,sp+4)==0)++theme_stop;if(em_cpu.pc==0x1624)++driver_reset;}step();if(pitch_frame!=em_cpu.vdp.frames){pitch_frame=em_cpu.vdp.frames;uint8_t pitch[24];for(unsigned port=0;port<2;port++)for(unsigned i=0;i<12;i++)pitch[port*12+i]=em_cpu.ym2612_stub.registers[port][0xa0+i];if(memcmp(pitch,last_pitch,sizeof pitch)){++pitch_updates;memcpy(last_pitch,pitch,sizeof pitch);}}}
static void music_frames(unsigned n){uint64_t end=em_cpu.vdp.frames+n;while(em_cpu.vdp.frames<end)music_step();}
static void music_route(int target){check(em_web_campaign_route_request(&em_cpu,target),"frontend route accepted");uint64_t end=em_cpu.vdp.frames+3000;while(em_web_campaign.route_pending&&em_cpu.vdp.frames<end)music_step();check(!em_web_campaign.route_pending,"frontend route complete");}
static void music_toggle(int row){check(em_web_campaign_input_request(&em_cpu,2,row),"original Options toggle");uint64_t end=em_cpu.vdp.frames+300;while((em_web_campaign.input_pending||em_web_campaign.sound_active)&&em_cpu.vdp.frames<end)music_step();music_frames(12);}
int main(void){em_cpu.rom=rom_data;em_cpu.rom_size=sizeof rom_data;em_cpu.audio_mode=AUDIO_ON;check(audio_init(&em_cpu,NULL),"real YMFM");em_host.dune_mouse.enabled=1;load("web/frontend.state.bin");em_web_campaign_frontend_audio_request(&em_cpu,1);em_web_campaign.frontend_hold=1;wait_ready("main",30);check(em_web_campaign.frontend_audio_active&&em_web_campaign.frontend_music_running,"native running frontend theme recognized");check(em_web_campaign_rom_long(&em_cpu,0x2dd5c)==0xffffffffu,"native Main bank mapping exists");check(em_cpu.rom[0xcf970]==0x1a&&em_cpu.rom[0xcf971]==0,"actual CF970 bank has13entries");theme_play=theme_stop=driver_reset=0;uint64_t samples=em_cpu.audio.frames,z80=em_cpu.z80_cpu.steps;
 music_route(1);music_frames(300);music_route(0);check(!theme_play&&!theme_stop&&!driver_reset,"Options/Main has no Theme0 restart/stop or driver reload");check(em_cpu.audio.frames>samples&&em_cpu.z80_cpu.steps>z80&&em_web_campaign.frontend_music_running,"original music engine advances throughout menus");puts("PASS native frontend Theme0 continuous through Main/Options/Main, no play/stop/reload");fflush(stdout);
 music_route(1);music_toggle(0);check(!em_cpu.ram[0xdc50]&&!em_web_campaign.frontend_music_running&&theme_stop==1,"original Music OFF stops actual Theme0 once");music_toggle(0);check(em_cpu.ram[0xdc50]&&em_web_campaign.frontend_music_running&&theme_play==1,"original Music ON resumes actual Theme0 once");unsigned play=theme_play,stop=theme_stop;music_toggle(1);music_toggle(1);check(em_cpu.ram[0xdc51]&&theme_play==play&&theme_stop==stop,"native Sound toggles do not restart music");music_route(0);check(theme_play==play&&theme_stop==stop&&!driver_reset,"return Main retains resumed track");puts("PASS original native Music/Sound handlers, real OFF/ON, no duplicate music commands");fflush(stdout);
 unsigned native_play=theme_play,native_stop=theme_stop;for(unsigned segment=0;segment<3;segment++){if(segment==1)music_route(1);if(segment==2)music_route(0);for(unsigned window=0;window<10;window++){uint64_t writes=em_cpu.ym2612_stub.writes;uint8_t streams[128];memcpy(streams,em_cpu.z80_bus.ram+0x1b80,sizeof streams);music_frames(600);check(em_cpu.ym2612_stub.writes>writes+100,"real YM register stream cannot freeze on last note");check(memcmp(streams,em_cpu.z80_bus.ram+0x1b80,sizeof streams),"native music stream/timers progress throughout full-song tail");check(em_web_campaign.frontend_audio_active&&em_web_campaign.frontend_music_running,"clean frontend audio policy remains active");printf("AUDIO segment%u window%u nativeFrame%llu YMwrites+%llu\n",segment,window,(unsigned long long)em_cpu.vdp.frames,(unsigned long long)(em_cpu.ym2612_stub.writes-writes));fflush(stdout);}}check(pitch_updates>20,"actual native YM frequency registers change over multi-note loops");check(theme_play==native_play&&theme_stop==native_stop&&!driver_reset,"18000frames Main/Options/Main retain one original never-restarted theme");printf("PASS real YMFM 18000 native frames: original Theme0 infinite multi-note loops continue, %u pitch updates, no held-note freeze or synthetic restart\n",pitch_updates);fflush(stdout);
 check(em_web_campaign_request(&em_cpu,1,1),"original campaign request");check(!em_web_campaign.frontend_audio_active&&!em_web_campaign.frontend_audio_requested,"campaign releases frontend audio policy");uint64_t end=em_cpu.vdp.frames+6000;while(em_web_campaign.stage!=4&&em_cpu.vdp.frames<end)music_step();check(em_web_campaign.stage==4&&driver_reset>0&&theme_stop>stop,"original campaign audio stop/profile reload executes unchanged");check(!em_web_campaign.outcome_seq,"audio presentation cannot award completion");printf("PASS campaign native audio preserved; frontend suppressed presentation calls=%llu native music changes=%llu\n",(unsigned long long)em_web_campaign.frontend_audio_suppressed,(unsigned long long)em_web_campaign.frontend_music_commands);audio_finish(&em_cpu);return 0;}
